class Utils {
public:
    static vector<long long> ntimes(int n, function<long long()> func, bool returnResults = false) {
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) {
            long long result = func();
            if (returnResults) a[i] = result;
        }
        return a;
    }
    static void cumsum(map<long long,long long>& a) {
        long long sum = 0;
        for (auto &kv : a) {
            kv.second += sum;
            sum = kv.second;
        }
    }
    static void diff(map<long long,long long>& a) {
        long long prev = 0;
        for (auto &kv : a) {
            long long buf = kv.second;
            kv.second -= prev;
            prev = buf;
        }
    }
    static int bitCount(long long n) {
        int cnt = 0;
        for (long long j = n; j; j >>= 1) cnt += (j & 1);
        return cnt;
    }
};

class PrimeUtils {
protected:
    static map<long long, map<long long,bool>> divisorsCache;
    static map<long long,long long> primes;
public:
    static vector<long long> primesGen(int limit) {
        int size = (limit >> 3) + 1;
        vector<unsigned char> a(size, (unsigned char)85);
        a[0] = (unsigned char)83;
        for (int i = 3; i * i < limit; i += 2) {
            if (a[i >> 3] & (1 << (i % 8))) {
            } else {
                for (int k = i; k * i < limit; k++) {
                    int n = k * i;
                    a[n >> 3] = (unsigned char)(a[n >> 3] | (1 << (n % 8)));
                }
            }
        }
        vector<long long> res;
        res.push_back(2);
        for (int i = 3; i < limit; i += 2) {
            if (!(a[i >> 3] & (1 << (i % 8)))) res.push_back(i);
        }
        return res;
    }

    static map<long long,bool> divisors(long long n, long long lp = 2) {
        auto it = divisorsCache.find(n);
        if (it != divisorsCache.end()) return it->second;
        if (primes.empty()) {
            vector<long long> ps = primesGen(1000);
            for (auto prime : ps) primes[prime] = prime;
        }
        map<long long,bool> r;
        for (auto &kv : primes) {
            long long p = kv.first;
            if (p >= lp) {
                if (n < p * p) {
                    r[1] = true;
                    r[n] = true;
                    break;
                } else if (n % p == 0) {
                    vector<long long> pres = {1, p};
                    map<long long,bool> nxtDiv = divisors(n / p, p);
                    for (auto pre : pres) {
                        for (auto &nv : nxtDiv) {
                            long long nxt = nv.first;
                            r[nxt * pre] = true;
                        }
                    }
                    break;
                }
            }
        }
        divisorsCache[n] = r;
        return divisorsCache[n];
    }
};

